use std :: path :: Path ; use std :: sync :: Arc ; use anyhow :: { Context , Result } ; use forge_domain :: * ; use schemars :: JsonSchema ; use serde :: Deserialize ; use crate :: services :: { AgentRegistry , AppConfigService , ProviderAuthService , ProviderService , ShellService , TemplateService , } ; use crate :: { AgentProviderResolver , EnvironmentInfra , Services } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Builds the `git commit` shell command string."] # [doc = ""] # [doc = " When `use_forge_committer` is true, prefixes the command with"] # [doc = " `GIT_COMMITTER_NAME` and `GIT_COMMITTER_EMAIL` environment variables"] # [doc = " to set ForgeCode as the committer."] fn build_commit_command (message : & str , flags : & str , use_forge_committer : bool) -> String { let escaped_message = message . replace ('\'' , r"'\''") ; if use_forge_committer { format ! ("GIT_COMMITTER_NAME='ForgeCode' GIT_COMMITTER_EMAIL='noreply@forgecode.dev' git commit {flags} -m '{escaped_message}'") } else { format ! ("git commit {flags} -m '{escaped_message}'") } }